import { createHash } from 'node:crypto';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { createRequire } from 'node:module';
import path from 'node:path';

const mobileRoot = path.resolve(import.meta.dirname, '..');
const require = createRequire(path.join(mobileRoot, 'package.json'));
const leafletRoot = path.dirname(require.resolve('leaflet/package.json'));
const webviewRoot = path.dirname(require.resolve('react-native-webview/package.json'));
const feature = path.join(mobileRoot, 'src/features/damage-map');
const check = process.argv.includes('--check');
const hash = (text) => createHash('sha256').update(text).digest('base64');
const manifest = JSON.parse(await readFile(path.join(leafletRoot, 'package.json'), 'utf8'));
if (manifest.version !== '1.9.4') throw new Error('Only reviewed Leaflet 1.9.4 is allowed.');
const originalJs = await readFile(path.join(leafletRoot, 'dist/leaflet.js'), 'utf8');
let css = await readFile(path.join(leafletRoot, 'dist/leaflet.css'), 'utf8');
if (hash(originalJs) !== '20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo='
  || hash(css) !== 'p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=') {
  throw new Error('Leaflet distribution integrity mismatch. Do not substitute another source.');
}
for (const name of ['layers.png', 'layers-2x.png', 'marker-icon.png']) {
  const data = await readFile(path.join(leafletRoot, 'dist/images', name));
  css = css.replaceAll(`images/${name}`, `data:image/png;base64,${data.toString('base64')}`);
}
if (/url\(\s*["']?images\//.test(css)) throw new Error('Unbundled CSS image URL.');
// No remote source-map lookup in a packaged local document. Hash the exact embedded text.
const normalize = (text) => text.replace(/\r\n?/g, '\n');
const scriptSafe = (text) => normalize(text).replace(/<\/script/gi, '<\\/script');
const js = scriptSafe(originalJs.replace(/\/\/# sourceMappingURL=.*$/m, '').trim());
const runtime = scriptSafe(await readFile(path.join(feature, 'mapRuntime.js'), 'utf8'));
const notices = normalize(`RoadSense mobile map — third party notices\n\nLeaflet 1.9.4\n${await readFile(path.join(leafletRoot, 'LICENSE'), 'utf8')}\n\nreact-native-webview 13.16.1\n${await readFile(path.join(webviewRoot, 'LICENSE'), 'utf8')}\n`);
const values = { LEAFLET_JS: js, LEAFLET_CSS: css, MAP_RUNTIME_JS: runtime, LEAFLET_SCRIPT_HASH: hash(js), MAP_RUNTIME_HASH: hash(runtime), THIRD_PARTY_NOTICES: notices };
const generated = '// Generated by scripts/prepare-map-assets.mjs. Do not edit; no runtime network scripts.\n'
  + Object.entries(values).map(([name, value]) => `export const ${name} = ${JSON.stringify(value)};`).join('\n') + '\n';
for (const [file, expected] of [[path.join(feature, 'generated/leafletAssets.ts'), generated], [path.join(mobileRoot, 'THIRD_PARTY_NOTICES.txt'), notices]]) {
  if (check) {
    const actual = await readFile(file, 'utf8').catch(() => '');
    if (normalize(actual) !== expected) throw new Error(`Stale map asset: ${path.relative(mobileRoot, file)}. Run npm run map:assets --workspace=mobile.`);
  } else {
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, expected);
  }
}
console.log(check ? 'Local map assets and licences verified.' : 'Local map assets and licences prepared.');
